cat > /tmp/factor.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gmp.h>

void pollard_rho(mpz_t factor, mpz_t n, unsigned long c) {
    mpz_t x, y, d, tmp;
    mpz_init(x);
    mpz_init(y);
    mpz_init(d);
    mpz_init(tmp);

    mpz_set_ui(x, 2);
    mpz_set_ui(y, 2);
    mpz_set_ui(d, 1);

    long count = 0;
    while (mpz_cmp_ui(d, 1) == 0) {
        // x = (x^2 + c) mod n
        mpz_mul(tmp, x, x);
        mpz_add_ui(tmp, tmp, c);
        mpz_mod(x, tmp, n);

        // y = (y^2 + c)^2 + c) mod n (twice)
        mpz_mul(tmp, y, y);
        mpz_add_ui(tmp, tmp, c);
        mpz_mod(y, tmp, n);
        mpz_mul(tmp, y, y);
        mpz_add_ui(tmp, tmp, c);
        mpz_mod(y, tmp, n);

        if (mpz_cmp(x, y) > 0)
            mpz_sub(tmp, x, y);
        else
            mpz_sub(tmp, y, x);

        mpz_gcd(d, tmp, n);
        count++;
        if (count % 100000 == 0) fprintf(stderr, "c=%lu iter=%ld\n", c, count);
        if (count > 10000000) break;
    }

    mpz_set(factor, d);
    mpz_clear(x);
    mpz_clear(y);
    mpz_clear(d);
    mpz_clear(tmp);
}

int main() {
    mpz_t n, factor;
    mpz_init(n);
    mpz_init(factor);

    mpz_set_str(n, "1422450808944701344261903748621562998784243662042303391362692043823716783771691667", 10);

    for (unsigned long c = 1; c <= 100; c++) {
        pollard_rho(factor, n, c);
        if (mpz_cmp_ui(factor, 1) != 0 && mpz_cmp(factor, n) != 0) {
            gmp_printf("Found factor with c=%lu: %Zd\n", c, factor);
            mpz_clear(n);
            mpz_clear(factor);
            return 0;
        }
        fprintf(stderr, "c=%lu: no factor\n", c);
    }
    printf("No factor found\n");
    mpz_clear(n);
    mpz_clear(factor);
    return 1;
}
