/* Brent's improved Pollard rho with batch GCD */
int brent_rho(mpz_t factor, const mpz_t n, unsigned long c_val) {
    mpz_t x, y, ys, q, g, c, tmp, diff;
    mpz_inits(x, y, ys, q, g, c, tmp, diff, NULL);

    mpz_set_ui(c, c_val);
    mpz_set_ui(y, 1);
    mpz_set_ui(q, 1);
    mpz_set_ui(g, 1);

    unsigned long r = 1, m = 512, k;

    while (mpz_cmp_ui(g, 1) == 0) {
        mpz_set(x, y);
        for (unsigned long i = 0; i < r; i++) {
            mpz_mul(tmp, y, y);
            mpz_add(tmp, tmp, c);
            mpz_mod(y, tmp, n);
        }
        k = 0;
        while (k < r && mpz_cmp_ui(g, 1) == 0) {
            mpz_set(ys, y);
            unsigned long steps = m < r - k ? m : r - k;
            for (unsigned long i = 0; i < steps; i++) {
                mpz_mul(tmp, y, y);
                mpz_add(tmp, tmp, c);
                mpz_mod(y, tmp, n);
                if (mpz_cmp(x, y) > 0)
                    mpz_sub(diff, x, y);
                else
                    mpz_sub(diff, y, x);
                mpz_mul(q, q, diff);
                mpz_mod(q, q, n);
            }
            mpz_gcd(g, q, n);
            k += m;
        }
        r *= 2;
    }

    if (mpz_cmp(g, n) == 0) {
        mpz_set_ui(g, 1);
        while (mpz_cmp_ui(g, 1) == 0) {
            mpz_mul(tmp, ys, ys);
            mpz_add(tmp, tmp, c);
            mpz_mod(ys, tmp, n);
            if (mpz_cmp(x, ys) > 0)
                mpz_sub(diff, x, ys);
            else
                mpz_sub(diff, ys, x);
            mpz_gcd(g, diff, n);
        }
    }

    int found = 0;
    if (mpz_cmp_ui(g, 1) != 0 && mpz_cmp(g, n) != 0) {
        mpz_set(factor, g);
        found = 1;
    }

    mpz_clears(x, y, ys, q, g, c, tmp, diff, NULL);
    return found;
}

int main() {
    mpz_t n, p, q, phi, d, c, m;
    mpz_inits(n, p, q, phi, d, c, m, NULL);

    mpz_set_str(n, "1422450808944701344261903748621562998784243662042303391362692043823716783771691667", 10);
    mpz_set_str(c, "843044897663847841476319711639772861390329326681532977209935413827620909782846667", 10);

    unsigned long e = 65537;

    printf("Factoring N...\n"); fflush(stdout);

    time_t start = time(NULL);
    for (unsigned long c_val = 1; c_val <= 1000000; c_val++) {
        if (brent_rho(p, n, c_val)) {
            mpz_divexact(q, n, p);
            gmp_printf("Found with c=%lu!\np=%Zd\nq=%Zd\n", c_val, p, q);

            /* Compute phi = (p-1)(q-1) */
            mpz_t p1, q1;
            mpz_inits(p1, q1, NULL);
            mpz_sub_ui(p1, p, 1);
            mpz_sub_ui(q1, q, 1);
            mpz_mul(phi, p1, q1);

            /* Compute d = e^{-1} mod phi */
            mpz_t e_mpz;
            mpz_init(e_mpz);
            mpz_set_ui(e_mpz, e);
            mpz_invert(d, e_mpz, phi);

            /* Decrypt: m = c^d mod n */
            mpz_powm(m, c, d, n);

            /* Convert to bytes */
            size_t sz = (mpz_sizeinbase(m, 2) + 7) / 8;
            unsigned char *buf = malloc(sz + 1);
