            buf[sz] = 0;
            printf("Flag: %s\n", buf);
            free(buf);

            mpz_clears(p1, q1, e_mpz, NULL);
            fflush(stdout);
            return 0;
        }
        if (c_val % 1000 == 0) {
            fprintf(stderr, "c=%lu, elapsed=%lds\n", c_val, time(NULL)-start);
            fflush(stderr);
        }
    }
    printf("Not found\n");
    mpz_clears(n, p, q, phi, d, c, m, NULL);
    return 1;
}
