# Write a proper ECM implementation in C with GMP
cat > /tmp/ecm_gmp.c << 'CEOF'
#include "/usr/local/lib/python3.12/dist-packages/gmpy2/gmp.h"
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct { mpz_t x, z; } Point;

void point_init(Point *P) { mpz_inits(P->x, P->z, NULL); }
void point_clear(Point *P) { mpz_clears(P->x, P->z, NULL); }
void point_set(Point *P, Point *Q) { mpz_set(P->x, Q->x); mpz_set(P->z, Q->z); }

/* Montgomery curve arithmetic */
void mont_add(Point *R, Point *P, Point *Q, Point *diff, mpz_t n) {
    mpz_t u, v, tmp;
    mpz_inits(u, v, tmp, NULL);

    mpz_sub(u, P->x, P->z);
    mpz_add(v, Q->x, Q->z);
    mpz_mul(u, u, v);  /* u = (P.x - P.z)(Q.x + Q.z) */

    mpz_add(v, P->x, P->z);
    mpz_t w; mpz_init(w);
    mpz_sub(w, Q->x, Q->z);
    mpz_mul(v, v, w);  /* v = (P.x + P.z)(Q.x - Q.z) */
    mpz_clear(w);

    /* R.x = diff.z * (u + v)^2 */
    mpz_add(tmp, u, v);
    mpz_mul(tmp, tmp, tmp);
    mpz_mul(R->x, tmp, diff->z);
    mpz_mod(R->x, R->x, n);

    /* R.z = diff.x * (u - v)^2 */
    mpz_sub(tmp, u, v);
    mpz_mul(tmp, tmp, tmp);
    mpz_mul(R->z, tmp, diff->x);
    mpz_mod(R->z, R->z, n);

    mpz_clears(u, v, tmp, NULL);
}

void mont_dbl(Point *R, Point *P, mpz_t a24, mpz_t n) {
    mpz_t u, v, tmp;
    mpz_inits(u, v, tmp, NULL);

    mpz_add(u, P->x, P->z);
    mpz_mul(u, u, u);  /* u = (x+z)^2 */

    mpz_sub(v, P->x, P->z);
    mpz_mul(v, v, v);  /* v = (x-z)^2 */

    mpz_mul(R->x, u, v);  /* R.x = u*v */
    mpz_mod(R->x, R->x, n);

    mpz_sub(tmp, u, v);  /* tmp = u - v = 4*x*z */
    mpz_mul(u, a24, tmp);
    mpz_add(u, u, v);    /* u = v + a24*(u-v) */
    mpz_mul(R->z, tmp, u);
    mpz_mod(R->z, R->z, n);

    mpz_clears(u, v, tmp, NULL);
}

/* Scalar multiplication: R = k*P on Montgomery curve */
void mont_mul(Point *R, Point *P, mpz_t k, mpz_t a24, mpz_t n) {
    int bits = (int)mpz_sizeinbase(k, 2);

    Point P0, P1;
    point_init(&P0); point_init(&P1);
    point_set(&P0, P);
    mont_dbl(&P1, P, a24, n);

    for (int i = bits - 2; i >= 0; i--) {
        if (mpz_tstbit(k, i)) {
            mont_add(&P0, &P0, &P1, P, n);
            mont_dbl(&P1, &P1, a24, n);
        } else {
            mont_add(&P1, &P0, &P1, P, n);
            mont_dbl(&P0, &P0, a24, n);
        }
    }

    point_set(R, &P0);
    point_clear(&P0); point_clear(&P1);
}

int ecm_one_curve(mpz_t factor, mpz_t n, unsigned long sigma, unsigned long B1) {
    mpz_t u, v, x, z, a24, g, tmp, k;
    mpz_inits(u, v, x, z, a24, g, tmp, k, NULL);

    /* Montgomery parametrization */
    mpz_set_ui(u, sigma);
    mpz_mul(u, u, u);
    mpz_sub_ui(u, u, 5);
    mpz_mod(u, u, n);

    mpz_set_ui(v, sigma);
    mpz_mul_ui(v, v, 4);
    mpz_mod(v, v, n);

    /* x = u^3, z = v^3 */
    mpz_powm_ui(x, u, 3, n);
    mpz_powm_ui(z, v, 3, n);

    /* a24 = (v-u)^3*(3u+v)/(4u^3*v) - 2 ... simplified form */
    /* Actually use: A = ((v-u)^3 * (3u+v)) / (4*u^3*v) - 2 */
    mpz_t vu, num, den, inv;
    mpz_inits(vu, num, den, inv, NULL);

    mpz_sub(vu, v, u);
    if (mpz_sgn(vu) < 0) mpz_add(vu, vu, n);

    mpz_powm_ui(num, vu, 3, n);
    mpz_mul_ui(tmp, u, 3);
    mpz_add(tmp, tmp, v);
    mpz_mod(tmp, tmp, n);
    mpz_mul(num, num, tmp);
    mpz_mod(num, num, n);

    mpz_powm_ui(den, u, 3, n);
    mpz_mul_ui(den, den, 4);
