    /* but we computed A already, so a24 = (A+2)*inv(4) mod n */
    mpz_add_ui(a24, a24, 2);
    mpz_mod(a24, a24, n);
    mpz_t four_inv;
    mpz_init(four_inv);
    mpz_set_ui(tmp, 4);
    mpz_invert(four_inv, tmp, n);
    mpz_mul(a24, a24, four_inv);
    mpz_mod(a24, a24, n);
