    Point P, R;
    point_init(&P); point_init(&R);
    mpz_set(P.x, x); mpz_set(P.z, z);

    /* Phase 1: multiply by all prime powers up to B1 */
    /* Generate primes and multiply */
    unsigned char *sieve = calloc(B1+1, 1);
    for (unsigned long i = 2; i <= B1; i++) {
        if (!sieve[i]) {
            unsigned long pp = i;
            while (pp <= B1) pp *= i;
