    mpz_gcd(g, P.z, n);
    int found = 0;
    if (mpz_cmp_ui(g, 1) != 0 && mpz_cmp(g, n) != 0) {
        mpz_set(factor, g);
        found = 1;
    }

    point_clear(&P); point_clear(&R);
    mpz_clears(u, v, x, z, a24, g, tmp, k, NULL);
    return found;
